using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Web.Script.Serialization;using XHLLauncher;
class ResilienceChecks {
 static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);count++;}
 static void Main(string[] args){try{Run(args);}catch(Exception ex){Console.WriteLine("FAIL "+ex.Message);Environment.ExitCode=1;}} static void Run(string[] args){string root=Path.Combine(args[0],"resilience-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);DateTime t=DateTime.UtcNow.AddMinutes(-20);Func<string,ResilienceGuard> make=n=>new ResilienceGuard(Path.Combine(root,n+".json"));
  var g=make("cold");Check(!g.Poll(true,false,false,false,t)&&!g.State.Pending,"Cold offline launch never starts an unobserved server");g.Poll(true,true,false,false,t);g.Poll(true,true,false,false,t.AddMinutes(2));Check(!g.State.Armed&&g.State.Phase=="Degraded","Query failures only degrade; they never arm crash recovery");g.Poll(true,true,true,false,t.AddMinutes(2));g.Poll(true,true,true,false,t.AddMinutes(2).AddSeconds(29));Check(!g.State.Armed,"Healthy arming requires a full 30 seconds");g.Poll(true,true,true,false,t.AddMinutes(2).AddSeconds(30));Check(g.State.Armed,"Query-confirmed stable session arms recovery");g.Poll(true,false,false,false,t.AddMinutes(3));Check(g.State.Pending&&!g.Poll(true,false,false,false,t.AddMinutes(3).AddSeconds(59)),"Observed exit waits at least 60 seconds");Check(!g.Poll(true,false,false,true,t.AddMinutes(4)),"Competing operations postpone recovery");Check(g.Poll(true,false,false,false,t.AddMinutes(4))&&g.State.Attempts.Count==1,"One eligible attempt is durably recorded before dispatch");Check(!g.Poll(true,false,false,false,t.AddMinutes(4).AddSeconds(1)),"Repeated polls cannot redispatch the same attempt");var uncertain=make("cold");Check(uncertain.Locked&&!uncertain.Poll(true,false,false,false,t.AddMinutes(5)),"Interrupted recovery is fail-closed across launcher restarts");g.Complete(false,"test failure");var restored=make("cold");Check(restored.State.Attempts.Count==1,"Attempt budget survives launcher restart");restored.Poll(true,true,true,false,t.AddMinutes(6));restored.Poll(true,true,true,false,t.AddMinutes(6).AddSeconds(31));restored.Poll(true,false,false,false,t.AddMinutes(7));Check(!restored.Poll(true,false,false,false,t.AddMinutes(8)),"Second crash increases cooldown to 120 seconds");Check(restored.Poll(true,false,false,false,t.AddMinutes(9))&&restored.State.Attempts.Count==2,"Second recovery uses the remaining hourly budget");restored.Complete(true,"test start");restored.Poll(true,true,true,false,t.AddMinutes(10));restored.Poll(true,true,true,false,t.AddMinutes(10).AddSeconds(31));restored.Poll(true,false,false,false,t.AddMinutes(11));Check(!restored.Poll(true,false,false,false,t.AddMinutes(15))&&restored.State.Phase=="Needs review","Third crash exhausts budget and requests review");
  var manual=make("manual");manual.Poll(true,true,true,false,t);manual.Poll(true,true,true,false,t.AddMinutes(1));manual.ManualStop();manual.Poll(true,false,false,false,t.AddMinutes(2));Check(!manual.Poll(true,false,false,false,t.AddMinutes(6))&&manual.State.ManualPause,"Manual Stop cannot be undone by automatic recovery");Check(make("manual").State.ManualPause,"Manual pause persists across launcher restart");manual.ManualStart();Check(!manual.State.ManualPause&&!manual.State.Armed,"Manual Start clears pause but does not invent healthy observations");File.WriteAllText(Path.Combine(root,"corrupt.json"),"broken");Check(make("corrupt").Locked,"Corrupt recovery journal blocks automatic starts");
  var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>("{\"gameSettings\":{\"foodBuffDurationFactor\":3,\"miningDamageFactor\":3,\"plantGrowthSpeedFactor\":4,\"resourceDropStackAmountFactor\":3,\"factoryProductionSpeedFactor\":4,\"enemyDamageFactor\":0.6,\"dayTimeDuration\":1800000000000}}");var proposed=ConfigAlignment.Proposed(data);Check(proposed.Count==5&&proposed.Values.All(v=>v==2),"Alignment clamps only the five unsupported values to the nearest limit");Check(!proposed.ContainsKey("gameSettings.enemyDamageFactor")&&!proposed.ContainsKey("gameSettings.dayTimeDuration"),"Valid difficulty values and durations are preserved");
  var initialPath=Path.Combine(root,"initial-plan.json");var initial=new BackupPlan(initialPath,30);Check(Math.Abs((new BackupPlan(initialPath,30).State.NextUtc-initial.State.NextUtc).TotalMilliseconds)<2,"Initial backup deadline persists before the first attempt");var backupPath=Path.Combine(root,"backup-plan.json");var plan=new BackupPlan(backupPath,30);plan.Begin(30,t);plan.Finish(true,"ok",30,t);var reloaded=new BackupPlan(backupPath,30);Check(Math.Abs((reloaded.State.NextUtc-t.AddMinutes(30)).TotalMilliseconds)<2&&Math.Abs((reloaded.State.LastSuccessUtc-t).TotalMilliseconds)<2,"Backup deadline and success persist across relaunch");plan.Begin(30,t);Check(new BackupPlan(backupPath,30).State.Paused,"Unknown backup outcome cannot cause an automatic duplicate copy");plan.Finish(false,"first",30,t);plan.Begin(30,t);plan.Finish(false,"second",30,t);plan.Begin(30,t);plan.Finish(false,"third",30,t);Check(plan.State.Paused&&!plan.Due(true,false,t.AddHours(1)),"Three consecutive backup failures pause automatic attempts");plan.Begin(30,t);plan.Finish(true,"manual repair",30,t);Check(!plan.State.Paused&&plan.State.Failures==0,"Successful owner-requested copy clears backup failure pause");
  Console.WriteLine(count+" resilience checks passed.");
 }
}



